export const THEMESEG_INNER = "\n      <button class=\"themebtn\" data-theme-set=\"auto\" role=\"radio\" aria-checked=\"false\" title=\"Use system theme\" aria-label=\"System theme\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M8 21h8M12 17v4\"/></svg></button>\n      <button class=\"themebtn\" data-theme-set=\"light\" role=\"radio\" aria-checked=\"false\" title=\"Use light theme\" aria-label=\"Light theme\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4.2\"/><path d=\"M12 2.6v2M12 19.4v2M4.4 12h-2M21.6 12h-2M6.3 6.3 4.9 4.9M19.1 19.1l-1.4-1.4M17.7 6.3l1.4-1.4M4.9 19.1l1.4-1.4\"/></svg></button>\n      <button class=\"themebtn\" data-theme-set=\"dark\" role=\"radio\" aria-checked=\"false\" title=\"Use dark theme\" aria-label=\"Dark theme\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M20.5 14.6A8.6 8.6 0 0 1 9.4 3.5a8.6 8.6 0 1 0 11.1 11.1Z\"/></svg></button>\n  ";

export const HEAD = "<meta charset=\"utf-8\">\n<title>Jobby is a free agent!</title>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#f7f3ed\" media=\"(prefers-color-scheme:light)\">\n<meta name=\"theme-color\" content=\"#141519\" media=\"(prefers-color-scheme:dark)\">\n<link rel=\"icon\" href=\"data:image/svg+xml;base64,\" type=\"image/svg+xml\">\n<link rel=\"icon\" href=\"data:image/x-icon;base64,\" sizes=\"32x32\">\n<link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\">\n<!-- Served from apps/web/public/. -->\n<link rel=\"manifest\" href=\"/site.webmanifest\">";

export const THEME_BOOT = "// Applied before first paint. Without this the page renders in the OS theme\n  // for a frame, then snaps to the saved one.\n  (function () {\n    try {\n      var t = localStorage.getItem('jobby.theme');\n      if (t === 'light' || t === 'dark') document.documentElement.dataset.theme = t;\n    } catch (e) {}\n    document.documentElement.classList.add('jb-intro');\n  })();";

export const THEME_WIRE = "var themeBtns = document.querySelectorAll('.themebtn');\n  var chrome = document.querySelectorAll('meta[name=\"theme-color\"]');\n  function paintTheme(mode) {\n    themeBtns.forEach(function (b) {\n      var on = b.dataset.themeSet === mode;\n      b.classList.toggle('on', on);\n      b.setAttribute('aria-checked', on ? 'true' : 'false');\n    });\n    // The two metas are media-scoped for the no-JS case; forcing a theme means\n    // pinning one of them on and the other off.\n    if (chrome.length === 2) {\n      chrome[0].media = mode === 'auto' ? '(prefers-color-scheme:light)'\n        : (mode === 'light' ? 'all' : 'not all');\n      chrome[1].media = mode === 'auto' ? '(prefers-color-scheme:dark)'\n        : (mode === 'dark' ? 'all' : 'not all');\n    }\n  }\n  function setTheme(mode) {\n    try {\n      if (mode === 'auto') localStorage.removeItem('jobby.theme');\n      else localStorage.setItem('jobby.theme', mode);\n    } catch (e) {}\n    if (mode === 'auto') delete document.documentElement.dataset.theme;\n    else document.documentElement.dataset.theme = mode;\n    paintTheme(mode);\n  }\n  themeBtns.forEach(function (b) {\n    b.addEventListener('click', function () { setTheme(b.dataset.themeSet); });\n  });\n  paintTheme(document.documentElement.dataset.theme || 'auto');";

export const HERO_INTRO = "var heroMark = document.querySelector('.jb-morph');\n  var heroWipe = document.querySelector('.jb-mascot2 .jm2-wipe-rect');\n  var introTimer = null;\n  function endIntro() { document.documentElement.classList.remove('jb-intro'); }\n  function playIntro() {\n    var root = document.documentElement;\n    root.classList.remove('jb-intro');\n    void root.offsetWidth;\n    root.classList.add('jb-intro');\n    clearTimeout(introTimer);\n    introTimer = setTimeout(endIntro, 2600);\n  }\n  if (heroWipe) heroWipe.addEventListener('animationend', endIntro);\n  introTimer = setTimeout(endIntro, 2600);\n  if (heroMark) {\n    heroMark.addEventListener('click', playIntro);\n    heroMark.addEventListener('keydown', function (event) {\n      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); playIntro(); }\n    });\n  }";

export const SELECT_SCRIPT = "\n(function () {\n  var nativeValue = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');\n  var openWrap = null;\n\n  function closeOpen() {\n    if (!openWrap) return;\n    openWrap.setAttribute('data-open', 'false');\n    openWrap.querySelector('.jb-select-btn').setAttribute('aria-expanded', 'false');\n    openWrap = null;\n  }\n\n  function enhance(select) {\n    if (select.multiple || select.dataset.jbSelect) return;\n    select.dataset.jbSelect = 'on';\n\n    var wrap = document.createElement('div');\n    wrap.className = 'jb-select';\n    wrap.setAttribute('data-open', 'false');\n    select.parentNode.insertBefore(wrap, select);\n    wrap.appendChild(select);\n    select.setAttribute('tabindex', '-1');\n    select.setAttribute('aria-hidden', 'true');\n\n    var btn = document.createElement('button');\n    btn.type = 'button';\n    btn.className = 'jb-select-btn';\n    btn.setAttribute('aria-haspopup', 'listbox');\n    btn.setAttribute('aria-expanded', 'false');\n    var described = select.getAttribute('aria-label');\n    if (described) btn.setAttribute('aria-label', described);\n\n    var valueText = document.createElement('span');\n    valueText.className = 'jb-select-value';\n    var chevron = document.createElement('span');\n    chevron.className = 'jb-select-chevron';\n    chevron.setAttribute('aria-hidden', 'true');\n    btn.appendChild(valueText);\n    btn.appendChild(chevron);\n\n    var menu = document.createElement('div');\n    menu.className = 'jb-select-menu';\n    menu.setAttribute('role', 'listbox');\n\n    var buttons = [];\n    Array.prototype.forEach.call(select.options, function (option, index) {\n      var item = document.createElement('button');\n      item.type = 'button';\n      item.className = 'jb-select-opt';\n      item.setAttribute('role', 'option');\n      item.textContent = option.textContent;\n      item.addEventListener('click', function () { choose(index); });\n      menu.appendChild(item);\n      buttons.push(item);\n    });\n\n    wrap.appendChild(btn);\n    wrap.appendChild(menu);\n\n    function sync() {\n      var current = select.options[select.selectedIndex];\n      valueText.textContent = current ? current.textContent : '';\n      buttons.forEach(function (item, index) {\n        item.setAttribute('aria-selected', index === select.selectedIndex ? 'true' : 'false');\n      });\n    }\n\n    function choose(index) {\n      if (select.selectedIndex !== index) {\n        select.selectedIndex = index;\n        sync();\n        select.dispatchEvent(new Event('input', { bubbles: true }));\n        select.dispatchEvent(new Event('change', { bubbles: true }));\n      }\n      closeOpen();\n      btn.focus();\n    }\n\n    function open() {\n      if (openWrap === wrap) { closeOpen(); return; }\n      closeOpen();\n      openWrap = wrap;\n      wrap.setAttribute('data-open', 'true');\n      btn.setAttribute('aria-expanded', 'true');\n      // Flipped upward when the menu would run off the bottom, which is most of\n      // the time for the sort control inside the Dropped dialog.\n      var room = window.innerHeight - btn.getBoundingClientRect().bottom;\n      wrap.classList.toggle('drop-up', room < Math.min(menu.scrollHeight + 16, 288));\n      var active = buttons[select.selectedIndex] || buttons[0];\n      if (active) active.focus();\n    }\n\n    function step(delta) {\n      var here = buttons.indexOf(document.activeElement);\n      var next = here < 0 ? select.selectedIndex : here + delta;\n      if (next < 0) next = buttons.length - 1;\n      if (next >= buttons.length) next = 0;\n      if (buttons[next]) buttons[next].focus();\n    }\n\n    btn.addEventListener('click', open);\n    btn.addEventListener('keydown', function (event) {\n      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); open(); }\n    });\n    menu.addEventListener('keydown', function (event) {\n      if (event.key === 'ArrowDown') { event.preventDefault(); step(1); }\n      else if (event.key === 'ArrowUp') { event.preventDefault(); step(-1); }\n      else if (event.key === 'Escape') { event.preventDefault(); closeOpen(); btn.focus(); }\n      else if (event.key === 'Tab') closeOpen();\n    });\n\n    // An implicit label forwards its clicks to the control it wraps, and the\n    // control it wraps is now invisible. Send them to the button instead.\n    var label = select.closest ? select.closest('label') : null;\n    if (label) label.addEventListener('click', function (event) {\n      if (btn.contains(event.target) || menu.contains(event.target)) return;\n      event.preventDefault();\n      btn.focus();\n    });\n\n    // Saved searches and Clear both assign to .value directly and dispatch\n    // nothing, so a listener alone would let the face drift out of step with\n    // the control it is meant to be showing.\n    Object.defineProperty(select, 'value', {\n      configurable: true,\n      get: function () { return nativeValue.get.call(this); },\n      set: function (next) { nativeValue.set.call(this, next); sync(); }\n    });\n    select.addEventListener('change', sync);\n    sync();\n  }\n\n  document.addEventListener('click', function (event) {\n    if (openWrap && !openWrap.contains(event.target)) closeOpen();\n  });\n  document.addEventListener('keydown', function (event) {\n    if (event.key === 'Escape') closeOpen();\n  });\n  document.querySelectorAll('select').forEach(enhance);\n  window.jobbyEnhanceSelects = function (root) {\n    (root || document).querySelectorAll('select').forEach(enhance);\n  };\n})();\n";
